    "text": "本田さん、今度のスピーチ大会の招待客に出す招待状、作ってもらえる。去年ののが事務室のパソコンの中に保存してあるから、書式はそれを参考にして、日付とかテーマを変えて、宛名はまだ空欄でいいから。",
