    "text": "その布、お店にももうないんだよね。妹だけ違う布を使うわけには行かないし、参ったなあ。でも、今からデザイン変えるのもね。とりあえず、ワンピースはそのままで作って、リハーサルに持ってきて、 残った分でどんな衣装ができるかそのとき検討しよう。",
