    "text": "午前中については、少し予定に変更があります。事前のご案内では、まず新しい本の情報をコンピューターに入力する作業、その次に、破れた本の修理作業の見学、の順で行うことになっていましたが、ええ、、、コンピューターの不具合のため、この順番を逆にします。",
